const http = require('http');
const fs = require('fs');
const path = require('path');
const crypto = require('crypto');
const { pipeline } = require('stream/promises');

const UPLOAD_DIR = '/tmp/uploads';
const MAX_FILE_SIZE = 10 * 1024 * 1024;
const ALLOWED_TYPES = new Set(['image/png', 'image/jpeg', 'application/pdf']);

class UploadMetadata {
  constructor(filename, contentType, size) {
    this.id = crypto.randomUUID();
    this.originalName = filename;
    this.contentType = contentType;
    this.size = size;
    this.timestamp = Date.now();
  }

  toLogEntry() {
    return `[${new Date(this.timestamp).toISOString()}] id=${this.id} name=${this.originalName} type=${this.contentType} size=${this.size}`;
  }
}

class HeaderParser {
  static parseContentDisposition(header) {
    if (!header) return {};
    const params = {};
    const parts = header.split(';').map(s => s.trim());
    for (const part of parts) {
      const eqIdx = part.indexOf('=');
      if (eqIdx === -1) {
        params.type = part;
      } else {
        const key = part.substring(0, eqIdx).trim();
        let value = part.substring(eqIdx + 1).trim();
        if (value.startsWith('"') && value.endsWith('"')) {
          value = value.slice(1, -1);
        }
        params[key] = value;
      }
    }
    return params;
  }

  static sanitizeFilename(raw) {
    if (!raw) return 'unnamed';
    const basename = path.basename(raw);
    const cleaned = basename.replace(/[^a-zA-Z0-9._-]/g, '_');
    return cleaned || 'unnamed';
  }
}

class ResponseBuilder {
  constructor(res) {
    this.res = res;
    this.headers = new Map();
    this.statusCode = 200;
  }

  setStatus(code) {
    this.statusCode = code;
    return this;
  }

  setHeader(name, value) {
    this.headers.set(name, value);
    return this;
  }

  setContentDisposition(filename) {
    const encoded = this._encodeRFC5987(filename);
    this.headers.set('Content-Disposition', `attachment; filename*=UTF-8''${encoded}`);
    return this;
  }

  _encodeRFC5987(str) {
    return encodeURIComponent(str)
      .replace(/['()]/g, escape)
      .replace(/\*/g, '%2A');
  }

  send(body) {
    for (const [name, value] of this.headers) {
      this.res.setHeader(name, value);
    }
    this.res.writeHead(this.statusCode);
    this.res.end(body);
  }
}

class NotificationService {
  static buildRedirectUrl(uploadId, userCallback) {
    const base = '/upload/complete';
    if (!userCallback) return base;
    return `${base}?id=${uploadId}&next=${userCallback}`;
  }

  static sendNotification(res, metadata, callbackUrl) {
    const redirectTarget = this.buildRedirectUrl(metadata.id, callbackUrl);
    const builder = new ResponseBuilder(res);
    builder
      .setStatus(303)
      .setHeader('X-Upload-Id', metadata.id)
      .setHeader('X-Upload-Status', 'complete')
      .setHeader('Location', redirectTarget)
      .send(`Upload complete. Redirecting to ${redirectTarget}`);
  }
}

function extractCallbackFromBody(body) {
  try {
    const boundary = body.indexOf('\r\n');
    if (boundary === -1) return null;
    const headerSection = body.substring(0, body.indexOf('\r\n\r\n'));
    const lines = headerSection.split('\r\n');
    for (const line of lines) {
      if (line.toLowerCase().startsWith('x-callback:')) {
        return line.substring('x-callback:'.length).trim();
      }
    }
    return null;
  } catch {
    return null;
  }
}

function validateUpload(contentType, size) {
  if (!ALLOWED_TYPES.has(contentType)) {
    return { valid: false, error: 'Invalid content type' };
  }
  if (size > MAX_FILE_SIZE) {
    return { valid: false, error: 'File too large' };
  }
  return { valid: true };
}

const server = http.createServer(async (req, res) => {
  if (req.method === 'POST' && req.url === '/api/upload') {
    const chunks = [];
    for await (const chunk of req) {
      chunks.push(chunk);
    }
    const rawBody = Buffer.concat(chunks).toString('utf-8');

    const contentType = req.headers['content-type'] || 'application/octet-stream';
    const disposition = HeaderParser.parseContentDisposition(
      req.headers['content-disposition']
    );
    const filename = HeaderParser.sanitizeFilename(disposition.filename);

    const validation = validateUpload(contentType, Buffer.byteLength(rawBody));
    if (!validation.valid) {
      const builder = new ResponseBuilder(res);
      builder.setStatus(400).send(JSON.stringify({ error: validation.error }));
      return;
    }

    const metadata = new UploadMetadata(filename, contentType, Buffer.byteLength(rawBody));
    console.log(metadata.toLogEntry());

    const callbackUrl = extractCallbackFromBody(rawBody);

    NotificationService.sendNotification(res, metadata, callbackUrl);
  } else {
    res.writeHead(404);
    res.end('Not found');
  }
});

server.listen(3000, () => console.log('Upload service on :3000'));
